using Microsoft.EntityFrameworkCore;
using Taller.Aplicacion.Abstracciones.Persistencia;
using Taller.Aplicacion.DTOs.Reportes;
using Taller.Dominio.Enumeraciones;

namespace Taller.Infraestructura.Persistencia.Repositorios;
/// <summary>Consultas acotadas y proyectadas en SQL; los importes provienen de documentos, nunca del precio actual del catálogo.</summary>
public sealed class ReporteRepositorio(TallerDbContext contexto) : IReporteRepositorio
{
    private static readonly string[] AccionesTecnicas = ["ActividadTomada", "ActividadLiberada", "DiagnosticoRegistrado", "EvaluacionTomada", "EvaluacionLiberada", "EvaluacionAvanceGuardado", "EvaluacionFinalizada", "EjecucionTomada", "EjecucionLiberada", "EjecucionAvanceGuardado", "EjecucionInterrumpida", "TrabajoFinalizado", "HallazgoRegistrado", "PausaResuelta", "MaterialClienteRevisado", "PresupuestoAdicionalPreparado", "SeleccionParcialRevisada"];
    public Task<List<ReporteRegistroDto>> ListarCargaAsync(int? tecnico) => contexto.Atenciones.AsNoTracking().Where(a => (a.Estado == EstadoAtencion.PendienteDiagnostico || a.Estado == EstadoAtencion.EnEvaluacionTecnica || a.Estado == EstadoAtencion.EnEjecucion) && (!tecnico.HasValue || a.IdTecnicoEnActividad == null || a.IdTecnicoEnActividad == tecnico)).Select(a => new ReporteRegistroDto { Codigo = "A-" + a.IdAtencion, IdAtencion = a.IdAtencion, Fecha = a.FechaApertura, Descripcion = a.Vehiculo.Dominio + " · " + a.MotivoConsulta, Responsable = a.TecnicoEnActividad == null ? "Disponible para tomar" : a.TecnicoEnActividad.Apellido + ", " + a.TecnicoEnActividad.Nombre, Estado = a.Pausas.Any(p => p.FechaResolucion == null) ? "Con pausas pendientes" : a.IdTecnicoEnActividad == null ? "Disponible para tomar" : "Reservada", Grupo = a.Estado.ToString() }).ToListAsync();
    public Task<List<ReporteRegistroDto>> ListarAtencionesAsync(DateTime desde, DateTime hastaExclusivo) => contexto.Atenciones.AsNoTracking().Where(a => a.FechaApertura >= desde && a.FechaApertura < hastaExclusivo).Select(a => new ReporteRegistroDto { Codigo = "A-" + a.IdAtencion, IdAtencion = a.IdAtencion, Fecha = a.FechaApertura, Descripcion = a.Vehiculo.Dominio + " · " + a.Cliente.Apellido + ", " + a.Cliente.Nombre + " · " + a.MotivoConsulta, Responsable = a.UsuarioRecepcion.Apellido + ", " + a.UsuarioRecepcion.Nombre, Estado = a.Estado.ToString(), Grupo = a.Estado.ToString() }).ToListAsync();
    public async Task<List<ReporteRegistroDto>> ListarPresupuestosAsync(DateTime desde, DateTime hastaExclusivo, int? tecnico)
    {
        var propuestas = await contexto.Presupuestos.AsNoTracking().Where(p => p.Tipo == TipoPresupuesto.Reparacion && p.Vigente && p.FechaCreacion >= desde && p.FechaCreacion < hastaExclusivo && (!tecnico.HasValue || p.IdUsuarioCreacion == tecnico)).Select(p => new { p.IdPresupuesto, p.IdAtencion, p.FechaCreacion, p.Estado, Dominio = p.Atencion.Vehiculo.Dominio, Responsable = p.UsuarioCreacion.Apellido + ", " + p.UsuarioCreacion.Nombre, Detalles = p.Detalles.Select(d => new { d.Cantidad, d.PrecioUnitario, d.AceptadoPorCliente }).ToList() }).ToListAsync();
        // Se redondea cada ítem igual que en el documento original, antes de sumar. No se usa el precio del catálogo.
        return propuestas.Select(p => new ReporteRegistroDto { Codigo = "P-" + p.IdPresupuesto, IdAtencion = p.IdAtencion, Fecha = p.FechaCreacion, Descripcion = p.Dominio + " · Atención " + p.IdAtencion, Responsable = p.Responsable, Estado = p.Estado == EstadoPresupuesto.Aceptado && p.Detalles.Any(d => d.AceptadoPorCliente == false) ? "Aceptado parcialmente" : p.Estado.ToString(), Grupo = p.Estado.ToString(), Importe = p.Detalles.Sum(d => decimal.Round(d.Cantidad * d.PrecioUnitario, 2, MidpointRounding.AwayFromZero)), ImporteAceptado = p.Estado != EstadoPresupuesto.Aceptado ? 0 : p.Detalles.Where(d => d.AceptadoPorCliente == true).Sum(d => decimal.Round(d.Cantidad * d.PrecioUnitario, 2, MidpointRounding.AwayFromZero)) }).ToList();
    }

    public Task<List<ReporteRegistroDto>> ListarMovimientosAsync(DateTime desde, DateTime hastaExclusivo)
    {
        // Un solo comando SQL evita mezclar dos lecturas entre un cobro concurrente y su anulación.
        var medios = contexto.PagoMedios.AsNoTracking();
        var cobros = medios.Where(m => m.Pago.Fecha >= desde && m.Pago.Fecha < hastaExclusivo).Select(m => new { m.IdPago, m.Orden, m.Pago.Comprobante.IdAtencion, Fecha = m.Pago.Fecha, Descripcion = m.Pago.Comprobante.Dominio + " · " + m.Pago.Comprobante.Cliente, Responsable = m.Pago.UsuarioRegistroNombre, Anulacion = false, Grupo = m.NombreMedio, m.Importe });
        var anulaciones = medios.Where(m => m.Pago.Anulado && m.Pago.FechaAnulacion >= desde && m.Pago.FechaAnulacion < hastaExclusivo).Select(m => new { m.IdPago, m.Orden, m.Pago.Comprobante.IdAtencion, Fecha = m.Pago.FechaAnulacion!.Value, Descripcion = m.Pago.Comprobante.Dominio + " · " + m.Pago.MotivoAnulacion, Responsable = m.Pago.UsuarioAnulacion!.Apellido + ", " + m.Pago.UsuarioAnulacion.Nombre, Anulacion = true, Grupo = m.NombreMedio, Importe = -m.Importe });
        return cobros.Concat(anulaciones).Select(m => new ReporteRegistroDto { Codigo = (m.Anulacion ? "AN-R-" : "R-") + m.IdPago + "/" + m.Orden, IdAtencion = m.IdAtencion, Fecha = m.Fecha, Descripcion = m.Descripcion, Responsable = m.Responsable, Estado = m.Anulacion ? "Anulación" : "Cobro", Grupo = m.Grupo, Importe = m.Importe }).ToListAsync();
    }

    public Task<List<ReporteRegistroDto>> ListarSaldosAsync() => contexto.Comprobantes.AsNoTracking().Where(c => c.Total > c.TotalPagado).Select(c => new ReporteRegistroDto { Codigo = "L-" + c.IdComprobante, IdAtencion = c.IdAtencion, Fecha = c.FechaEmision, Descripcion = c.Dominio + " · " + c.Cliente, Responsable = c.UsuarioEmision.Apellido + ", " + c.UsuarioEmision.Nombre, Estado = c.TotalPagado == 0 ? "Sin cobros" : "Cobrado parcialmente", Grupo = c.TotalPagado == 0 ? "Sin cobros" : "Cobrado parcialmente", Importe = c.Total - c.TotalPagado }).ToListAsync();
    public Task<List<ReporteRegistroDto>> ListarActividadAsync(DateTime desde, DateTime hastaExclusivo, int? tecnico) => contexto.HistorialAtenciones.AsNoTracking().Where(h => h.Fecha >= desde && h.Fecha < hastaExclusivo && AccionesTecnicas.Contains(h.Accion) && (!tecnico.HasValue || h.IdUsuario == tecnico)).Select(h => new ReporteRegistroDto { Codigo = "EV-" + h.IdHistorialAtencion, IdAtencion = h.IdAtencion, Fecha = h.Fecha, Descripcion = h.Atencion.Vehiculo.Dominio + " · " + h.Accion + " · " + (h.Observaciones ?? ""), Responsable = h.Usuario.Apellido + ", " + h.Usuario.Nombre, Estado = h.Accion, Grupo = h.Accion }).ToListAsync();
    public Task<List<ReporteRegistroDto>> ListarConceptosAsync(DateTime desde, DateTime hastaExclusivo, int? tecnico) => contexto.PresupuestoDetalles.AsNoTracking().Where(d => d.CantidadEjecutada > 0 && d.FechaRegistroEjecucion >= desde && d.FechaRegistroEjecucion < hastaExclusivo && (!tecnico.HasValue || d.IdTecnicoRegistro == tecnico)).Select(d => new ReporteRegistroDto { Codigo = "ITEM-" + d.IdPresupuestoDetalle, IdAtencion = d.Presupuesto.IdAtencion, Fecha = d.FechaRegistroEjecucion!.Value, Descripcion = d.Descripcion + " · " + d.Presupuesto.Atencion.Vehiculo.Dominio, Responsable = d.TecnicoRegistro!.Apellido + ", " + d.TecnicoRegistro.Nombre, Estado = d.EstadoEjecucion.ToString(), Grupo = d.Concepto.Tipo.ToString(), Cantidad = d.CantidadEjecutada, Importe = decimal.Round(d.CantidadEjecutada * d.PrecioUnitario, 2, MidpointRounding.AwayFromZero) }).ToListAsync();
}
